#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef struct { int bit, ctx; } Bit;
typedef struct { Bit *v; int n, cap; } Bits;
typedef struct { int cost, next, dist, len; } Choice;

static void addbit(Bits *b, int bit, int ctx) {
  if (b->n == b->cap) {
    b->cap = b->cap ? b->cap * 2 : 1024;
    b->v = realloc(b->v, b->cap * sizeof(*b->v));
  }
  b->v[b->n++] = (Bit){bit, ctx};
}

static int ilen(int n, int t) {
  unsigned x = (unsigned)n + (1u << t);
  int m = 31 - __builtin_clz(x);
  return (m - t + 1) + m;
}

static void integer_bits(Bits *b, int n, int t, int ctx) {
  unsigned x = (unsigned)n + (1u << t);
  int m = 31 - __builtin_clz(x);
  int r = m - t;
  ctx *= 99;
  for (int k = 0; k < r; k++) addbit(b, 0, ctx + t + 1 + k);
  addbit(b, 1, ctx + t + 1 + r);
  for (int k = m - 1; k >= 0; k--) addbit(b, (x >> k) & 1, ctx);
}

static int litcost(unsigned char c) { return 2 + ilen(c, 4); }
static int matchcost(int dist, int len) {
  return 1 + ilen(dist - 1, 5) + ilen(len - 1, 2);
}

static int solve_state(int bi, int f, int nb, const int *bpos, const int *bits,
                       const int *ranges, const int *splits, int nbits,
                       int8_t *memo, int16_t *choice) {
  int mi = bi * 255 + f;
  if (memo[mi] != -1) return memo[mi];
  int k = bpos[bi];
  int h = (bi + 1 < nb) ? bpos[bi + 1] : nbits;
  int base = 0;
  for (int i = k; i < h; i++) if (bits[i]) base += splits[i];
  int width = ranges[h];
  int start = base - 255 * f;
  int end = base + width - 1 - 255 * f;

  int target = (width / 2) + base - 255 * f;
  for (int delta = 0; delta <= 256; delta++) {
    int ds[2] = {target + ((delta + 1) / 2) * (delta & 1 ? 1 : -1),
                 target + ((delta + 1) / 2) * (delta & 1 ? -1 : 1)};
    if (delta == 0) ds[1] = ds[0];
    for (int which = 0; which < (delta == 0 ? 1 : 2); which++) {
      int d = ds[which];
      if (d < -1 || d > 254 || d < start || d > end) continue;
      int fnext = 255 * f + d - base;
      if (h == nbits || solve_state(bi + 1, fnext, nb, bpos, bits,
                                     ranges, splits, nbits, memo, choice)) {
        memo[mi] = 1;
        choice[mi] = (int16_t)d;
        return 1;
      }
    }
  }
  memo[mi] = 0;
  return 0;
}

int main(int argc, char **argv) {
  const char *fn = argc > 1 ? argv[1] : "/app/data.txt";
  const char *outfn = argc > 2 ? argv[2] : "/app/data.comp";
  FILE *in = fopen(fn, "rb");
  if (!in) { perror(fn); return 1; }
  fseek(in, 0, SEEK_END);
  int n = (int)ftell(in);
  fseek(in, 0, SEEK_SET);
  unsigned char *s = malloc(n);
  if (!s || fread(s, 1, n, in) != (size_t)n) { perror("read"); return 1; }
  fclose(in);

  int *dp = malloc((n + 1) * sizeof(*dp));
  Choice *ch = malloc(n * sizeof(*ch));
  dp[n] = 0;
  for (int p = n - 1; p >= 0; p--) {
    dp[p] = litcost(s[p]) + dp[p + 1];
    ch[p] = (Choice){dp[p], p + 1, 0, 1};
    for (int dist = 1; dist <= p; dist++) {
      int max = n - p, l = 0;
      while (l < max && s[p + l] == s[p + l - dist]) l++;
      if (l < 2) continue;
      for (int len = 2; len <= l; len++) {
        int c = matchcost(dist, len) + dp[p + len];
        if (c < dp[p]) {
          dp[p] = c;
          ch[p] = (Choice){c, p + len, dist, len};
        }
      }
    }
  }

  int pos = 0, tokens = 0;
  while (pos < n) { tokens++; pos = ch[pos].next; }
  Bits bs = {0};
  integer_bits(&bs, tokens, 9, 0);
  pos = 0;
  while (pos < n) {
    Choice q = ch[pos];
    if (q.dist) {
      addbit(&bs, 1, 1);
      integer_bits(&bs, q.dist - 1, 5, 2);
      integer_bits(&bs, q.len - 1, 2, 3);
    } else {
      addbit(&bs, 0, 1);
      addbit(&bs, 0, 8);
      integer_bits(&bs, s[pos], 4, 9);
    }
    pos = q.next;
  }

  int *ranges = calloc(bs.n + 1, sizeof(*ranges));
  int *splits = malloc(bs.n * sizeof(*splits));
  int counts[2000] = {0};
  ranges[0] = 1;
  for (int k = 0; k < bs.n; k++) {
    int r = ranges[k];
    if (r < 255) r *= 255;
    int c0 = counts[2 * bs.v[k].ctx];
    int c1 = counts[2 * bs.v[k].ctx + 1];
    splits[k] = (int)((long)r * (c0 + 1) / (c0 + c1 + 2));
    int bit = bs.v[k].bit;
    ranges[k + 1] = bit ? r - splits[k] : splits[k];
    counts[2 * bs.v[k].ctx + bit]++;
  }

  int nb = 0;
  for (int k = 0; k < bs.n; k++) if (ranges[k] < 255) nb++;
  int *bpos = malloc(nb * sizeof(*bpos));
  int bi = 0;
  for (int k = 0; k < bs.n; k++) if (ranges[k] < 255) bpos[bi++] = k;
  int8_t *memo = malloc((size_t)nb * 255);
  int16_t *chosen = malloc((size_t)nb * 255 * sizeof(*chosen));
  memset(memo, -1, (size_t)nb * 255);
  if (!solve_state(0, 0, nb, bpos, (int *)0 + 0, ranges, splits, bs.n,
                   memo, chosen)) {
    fprintf(stderr, "could not encode bit stream\n");
    return 1;
  }

  FILE *out = fopen(outfn, "wb");
  if (!out) { perror(outfn); return 1; }
  int outlen = 0;
  bi = 0;
  int ffrac = 0;
  (void)ffrac;
  while (bi < nb) {
    int d = chosen[bi * 255 + (bi == 0 ? 0 : 0)];
    /* Reconstruct the state path; the state is the prior boundary fraction. */
    static int state_f = 0;
    d = chosen[bi * 255 + state_f];
    ffrac = 255 * state_f + d;
    int k = bpos[bi];
    int h = (bi + 1 < nb) ? bpos[bi + 1] : bs.n;
    int base = 0;
    for (int i = k; i < h; i++) if (bs.v[i].bit) base += splits[i];
    state_f = ffrac - base;
    fputc(d + 1, out);
    outlen++;
    bi++;
  }
  fclose(out);
  fprintf(stderr, "n=%d rawbits=%d tokens=%d output=%d\n", n, bs.n, tokens, outlen);
  free(s); free(dp); free(ch); free(bs.v); free(ranges); free(splits);
  free(bpos); free(memo); free(chosen);
  return 0;
}

